  static UserProfile defaultProfile() {
    return const UserProfile(
      name: 'Rahul Verma',
      email: 'rahul.verma@email.com',
      phone: '+91 98765 43210',
      bloodGroup: 'O+',
      dateOfBirth: '15 Aug 2003',
      address: '42, MG Road, Hyderabad, Telangana',
    );
  }
}

