                        icon: Icons.person,
                        label: 'My\nProfile',
                        color: AppTheme.warning,
                        onTap: () =>
                            Navigator.pushNamed(context, '/profile'),
                      ),
                    ],
                  ),
                ),

                // ── Specialties (Syllabus: horizontal ListView, Chip)
                const SectionHeader(title: 'Browse Specialties'),
                SizedBox(
                  height: 50,
                  child: ListView(
                    scrollDirection: Axis.horizontal,
                    padding: const EdgeInsets.symmetric(horizontal: 16),
                    children: [
                      _SpecialtyChip(
                          label: '❤️ Cardiology',
                          onTap: () =>
                              Navigator.pushNamed(context, '/doctors')),
                      _SpecialtyChip(
                          label: '🧠 Neurology',
                          onTap: () =>
                              Navigator.pushNamed(context, '/doctors')),
                      _SpecialtyChip(
                          label: '🦴 Orthopedics',
                          onTap: () =>
                              Navigator.pushNamed(context, '/doctors')),
                      _SpecialtyChip(
                          label: '👶 Pediatrics',
                          onTap: () =>
                              Navigator.pushNamed(context, '/doctors')),
                      _SpecialtyChip(
                          label: '🩺 General',
                          onTap: () =>
                              Navigator.pushNamed(context, '/doctors')),
                      _SpecialtyChip(
                          label: '🌿 Dermatology',
                          onTap: () =>
                              Navigator.pushNamed(context, '/doctors')),
                    ],
                  ),
                ),

                // ── Top Doctors (Syllabus: ListView, DoctorCard custom widget)
                SectionHeader(
                  title: 'Top Doctors',
                  actionText: 'See All',
                  onActionTap: () =>
                      Navigator.pushNamed(context, '/doctors'),
                ),
                ...doctorProvider.filteredDoctors
                    .take(3)
                    .map(
                      (doctor) => DoctorCard(
                        doctor: doctor,
                        onTap: () => Navigator.pushNamed(
                          context,
                          '/doctor-detail',
                          arguments: doctor.id,
                        ),
                      ),
                    ),

                const SizedBox(height: 24),
              ],
            ),
          ),
        ],
      ),
      // Bottom Navigation Bar (Syllabus: Navigator)
      bottomNavigationBar: BottomNavigationBar(
        type: BottomNavigationBarType.fixed,
        selectedItemColor: AppTheme.primary,
        unselectedItemColor: AppTheme.textLight,
        currentIndex: 0,
        onTap: (index) {
          switch (index) {
            case 0:
              break;
            case 1:
              Navigator.pushNamed(context, '/doctors');
              break;
            case 2:
              Navigator.pushNamed(context, '/appointments');
              break;
            case 3:
              Navigator.pushNamed(context, '/profile');
              break;
          }
        },
        items: const [
          BottomNavigationBarItem(
              icon: Icon(Icons.home_outlined),
              activeIcon: Icon(Icons.home),
              label: 'Home'),
          BottomNavigationBarItem(
              icon: Icon(Icons.search_outlined),
              activeIcon: Icon(Icons.search),
              label: 'Doctors'),
          BottomNavigationBarItem(
              icon: Icon(Icons.calendar_today_outlined),
              activeIcon: Icon(Icons.calendar_today),
              label: 'Appointments'),
          BottomNavigationBarItem(
              icon: Icon(Icons.person_outline),
              activeIcon: Icon(Icons.person),
              label: 'Profile'),
        ],
      ),
    );
  }

  List<Widget> _buildStatCards(
      AppointmentProvider provider, bool isTablet) {
    return [
      StatCard(
        value: provider.upcoming.length.toString(),
        label: 'Upcoming',
        icon: Icons.upcoming,
        color: AppTheme.primary,
      ),
      StatCard(
        value: provider.completed.length.toString(),
        label: 'Completed',
        icon: Icons.check_circle_outline,
        color: AppTheme.success,
      ),
      StatCard(
        value: provider.cancelled.length.toString(),
        label: 'Cancelled',
        icon: Icons.cancel_outlined,
        color: AppTheme.error,
      ),
    ];
  }
}

// ─── Private helper widgets ───────────────────────────────────
class _ActionButton extends StatelessWidget {
  final IconData icon;
  final String label;
  final Color color;
  final VoidCallback onTap;

  const _ActionButton({
    required this.icon,
    required this.label,
    required this.color,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    return Expanded(
      child: GestureDetector(
        onTap: onTap,
        child: Container(
          padding: const EdgeInsets.symmetric(vertical: 14),
          decoration: BoxDecoration(
            color: color.withOpacity(0.1),
            borderRadius: BorderRadius.circular(12),
            border: Border.all(color: color.withOpacity(0.2)),
          ),
          child: Column(
            children: [
              Icon(icon, color: color, size: 26),
              const SizedBox(height: 6),
              Text(
                label,
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontSize: 11,
                  color: color,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _SpecialtyChip extends StatelessWidget {
  final String label;
  final VoidCallback onTap;

  const _SpecialtyChip({required this.label, required this.onTap});

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        margin: const EdgeInsets.only(right: 10),
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
        decoration: BoxDecoration(
          color: AppTheme.primary.withOpacity(0.08),
          borderRadius: BorderRadius.circular(24),
          border: Border.all(color: AppTheme.primary.withOpacity(0.3)),
        ),
        child: Text(
          label,
          style: const TextStyle(
            color: AppTheme.primary,
            fontSize: 13,
            fontWeight: FontWeight.w500,
          ),
        ),
      ),
    );
  }
}

