import 'package:flutter/material.dart';
import '../services/health_quote_service.dart';
import '../theme/app_theme.dart';

// Screen 7: Health Tips + Animations Demo Screen
// Syllabus coverage:
//   • AnimationController, FadeTransition, SlideTransition (Lab 8a, 8b)
//   • Fetch data from a REST API (Lab 9a)
//   • Display fetched data in a meaningful way (Lab 9b)
//   • StatefulWidget + setState (Lab 5)
//   • async/await, error handling in UI (Lab 10)
class HealthTipsScreen extends StatefulWidget {
  const HealthTipsScreen({super.key});

  @override
  State<HealthTipsScreen> createState() => _HealthTipsScreenState();
}

class _HealthTipsScreenState extends State<HealthTipsScreen>
    with TickerProviderStateMixin {
  // ── Animation controllers (Syllabus: AnimationController, Lab 8)
  late final AnimationController _headerController;
  late final AnimationController _listController;
  late final Animation<double> _headerFade;
  late final Animation<Offset> _headerSlide;
  late final Animation<double> _listFade;

  // ── API state (Syllabus: REST API fetch, Lab 9)
  List<QuoteModel> _quotes = [];
  bool _isLoading = false;
  String? _errorMessage;

  // ── Static health tips (always visible)
  final List<_HealthTip> _healthTips = const [
    _HealthTip(
      emoji: '💧',
      title: 'Stay Hydrated',
      description:
          'Drink at least 8 glasses of water daily to maintain optimal body function and energy levels.',
      color: Color(0xFF1565C0),
    ),
    _HealthTip(
      emoji: '🏃',
      title: 'Exercise Daily',
      description:
          '30 minutes of moderate exercise a day reduces risk of heart disease, diabetes and improves mood.',
      color: Color(0xFF2E7D32),
    ),
    _HealthTip(
      emoji: '😴',
      title: 'Sleep Well',
      description:
          '7–9 hours of quality sleep is essential for cognitive function, immunity and emotional health.',
      color: Color(0xFF4527A0),
    ),
    _HealthTip(
      emoji: '🥗',
      title: 'Eat Balanced',
      description:
          'A diet rich in fruits, vegetables, whole grains and lean proteins powers your body and brain.',
      color: Color(0xFFE65100),
    ),
    _HealthTip(
      emoji: '🧘',
      title: 'Manage Stress',
      description:
          'Practise meditation, yoga or deep breathing for 10 minutes a day to reduce chronic stress.',
      color: Color(0xFF00695C),
    ),
    _HealthTip(
      emoji: '🚭',
      title: 'Avoid Smoking',
      description:
          'Quitting smoking reduces risk of cancer, heart disease and stroke within weeks of stopping.',
      color: Color(0xFFC62828),
    ),
  ];

  @override
  void initState() {
    super.initState();

    // Header fade + slide (Syllabus: FadeTransition + SlideTransition, Lab 8)
    _headerController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 900),
    );
    _listController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 700),
    );

    _headerFade = CurvedAnimation(
      parent: _headerController,
      curve: Curves.easeIn,
    );
    _headerSlide = Tween<Offset>(
      begin: const Offset(0, -0.3),
      end: Offset.zero,
    ).animate(
      CurvedAnimation(parent: _headerController, curve: Curves.easeOutCubic),
    );
    _listFade = CurvedAnimation(
      parent: _listController,
      curve: Curves.easeIn,
    );

    _headerController.forward();
    Future.delayed(const Duration(milliseconds: 400), () {
      if (mounted) _listController.forward();
    });

    // Fetch quotes from REST API
    _fetchQuotes();
  }

  @override
  void dispose() {
    _headerController.dispose();
    _listController.dispose();
    super.dispose();
  }

  // ── REST API fetch (Syllabus: Lab 9a – fetch from REST API)
  Future<void> _fetchQuotes() async {
    setState(() {
      _isLoading = true;
      _errorMessage = null;
    });
    try {
      final quotes = await HealthQuoteService.fetchQuotes();
      if (mounted) {
        setState(() {
          _quotes = quotes;
          _isLoading = false;
        });
      }
    } catch (e) {
      if (mounted) {
        setState(() {
          _errorMessage =
              'Could not load quotes. Check your internet connection.';
          _isLoading = false;
        });
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Health Tips'),
        actions: [
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: 'Refresh quotes',
            onPressed: _fetchQuotes,
          ),
        ],
      ),
      body: SingleChildScrollView(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // ── Animated header banner (Syllabus: FadeTransition + SlideTransition)
            SlideTransition(
              position: _headerSlide,
              child: FadeTransition(
                opacity: _headerFade,
                child: Container(
                  width: double.infinity,
                  padding: const EdgeInsets.all(24),
                  decoration: const BoxDecoration(
                    gradient: LinearGradient(
                      colors: [AppTheme.primary, Color(0xFF006064)],
                      begin: Alignment.topLeft,
                      end: Alignment.bottomRight,
                    ),
                  ),
                  child: Column(
                    children: [
                      const Text('🏥', style: TextStyle(fontSize: 48)),
                      const SizedBox(height: 12),
                      const Text(
                        'Live Well Every Day',
                        style: TextStyle(
                          color: Colors.white,
                          fontSize: 22,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      const SizedBox(height: 8),
                      const Text(
                        'Small daily habits lead to big health improvements',
                        textAlign: TextAlign.center,
                        style: TextStyle(color: Colors.white70, fontSize: 13),
                      ),
                    ],
                  ),
                ),
              ),
            ),

            // ── Health Tips section (static, always visible)
            const Padding(
              padding: EdgeInsets.fromLTRB(16, 20, 16, 8),
              child: Text(
                '🌿 Daily Health Tips',
                style: TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                  color: AppTheme.textDark,
                ),
              ),
            ),

            // Animated tip cards (Syllabus: FadeTransition + AnimatedContainer)
            FadeTransition(
              opacity: _listFade,
              child: Column(
                children: _healthTips
                    .asMap()
                    .entries
                    .map((entry) => _AnimatedTipCard(
                          tip: entry.value,
                          delayMillis: entry.key * 100,
                        ))
                    .toList(),
              ),
            ),

            // ── REST API Quotes Section (Syllabus: Lab 9 – fetch & display)
            const Padding(
              padding: EdgeInsets.fromLTRB(16, 24, 16, 8),
              child: Row(
                children: [
                  Text(
                    '💬 Wellness Quotes',
                    style: TextStyle(
                      fontSize: 18,
                      fontWeight: FontWeight.bold,
                      color: AppTheme.textDark,
                    ),
                  ),
                  SizedBox(width: 8),
                  Text(
                    '(Live from API)',
                    style: TextStyle(
                      fontSize: 12,
                      color: AppTheme.textLight,
                      fontStyle: FontStyle.italic,
                    ),
                  ),
                ],
              ),
            ),

            if (_isLoading)
              const Padding(
                padding: EdgeInsets.symmetric(vertical: 32),
                child: Center(
                  child: Column(
                    children: [
                      CircularProgressIndicator(color: AppTheme.primary),
                      SizedBox(height: 12),
                      Text(
                        'Fetching inspirational quotes...',
                        style: TextStyle(color: AppTheme.textMedium),
                      ),
                    ],
                  ),
                ),
              )
            else if (_errorMessage != null)
              Padding(
                padding: const EdgeInsets.all(16),
                child: Container(
                  padding: const EdgeInsets.all(16),
                  decoration: BoxDecoration(
                    color: AppTheme.error.withOpacity(0.08),
                    borderRadius: BorderRadius.circular(12),
                    border:
                        Border.all(color: AppTheme.error.withOpacity(0.3)),
                  ),
                  child: Column(
                    children: [
                      const Icon(Icons.wifi_off,
                          color: AppTheme.error, size: 32),
                      const SizedBox(height: 8),
                      Text(
                        _errorMessage!,
                        textAlign: TextAlign.center,
                        style: const TextStyle(color: AppTheme.error),
                      ),
                      const SizedBox(height: 12),
                      ElevatedButton.icon(
                        onPressed: _fetchQuotes,
                        icon: const Icon(Icons.refresh),
                        label: const Text('Retry'),
                        style: ElevatedButton.styleFrom(
                            backgroundColor: AppTheme.error),
                      ),
                    ],
                  ),
                ),
              )
            else if (_quotes.isEmpty)
              const Padding(
                padding: EdgeInsets.all(24),
                child: Center(
                  child: Text(
                    'No quotes loaded yet. Tap refresh to try again.',
                    style: TextStyle(color: AppTheme.textLight),
                  ),
                ),
              )
            else
              // Display fetched data (Syllabus: Lab 9b – display in meaningful way)
              ListView.builder(
                shrinkWrap: true,
                physics: const NeverScrollableScrollPhysics(),
                padding: const EdgeInsets.fromLTRB(16, 0, 16, 8),
                itemCount: _quotes.length,
                itemBuilder: (ctx, i) {
                  final quote = _quotes[i];
                  return _QuoteCard(quote: quote, index: i);
                },
              ),

            const SizedBox(height: 32),
          ],
        ),
      ),
    );
  }
}

// ─── Animated Health Tip Card ─────────────────────────────────
class _AnimatedTipCard extends StatefulWidget {
  final _HealthTip tip;
  final int delayMillis;

  const _AnimatedTipCard({required this.tip, required this.delayMillis});

  @override
  State<_AnimatedTipCard> createState() => _AnimatedTipCardState();
}

class _AnimatedTipCardState extends State<_AnimatedTipCard>
    with SingleTickerProviderStateMixin {
  late final AnimationController _ctrl;
  late final Animation<Offset> _slide;
  late final Animation<double> _fade;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 500),
    );
    _slide = Tween<Offset>(
      begin: const Offset(0.4, 0),
      end: Offset.zero,
    ).animate(CurvedAnimation(parent: _ctrl, curve: Curves.easeOutCubic));
    _fade = CurvedAnimation(parent: _ctrl, curve: Curves.easeIn);

    Future.delayed(Duration(milliseconds: widget.delayMillis), () {
      if (mounted) _ctrl.forward();
    });
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SlideTransition(
      position: _slide,
      child: FadeTransition(
        opacity: _fade,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(16, 0, 16, 12),
          child: Container(
            padding: const EdgeInsets.all(16),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(16),
              boxShadow: [
                BoxShadow(
                  color: widget.tip.color.withOpacity(0.15),
                  blurRadius: 10,
                  offset: const Offset(0, 4),
                ),
              ],
              border: Border.all(
                color: widget.tip.color.withOpacity(0.2),
              ),
            ),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Container(
                  width: 48,
                  height: 48,
                  decoration: BoxDecoration(
                    color: widget.tip.color.withOpacity(0.1),
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Center(
                    child: Text(
                      widget.tip.emoji,
                      style: const TextStyle(fontSize: 24),
                    ),
                  ),
                ),
                const SizedBox(width: 14),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        widget.tip.title,
                        style: TextStyle(
                          fontSize: 15,
                          fontWeight: FontWeight.bold,
                          color: widget.tip.color,
                        ),
                      ),
                      const SizedBox(height: 4),
                      Text(
                        widget.tip.description,
                        style: const TextStyle(
                          fontSize: 13,
                          color: AppTheme.textMedium,
                          height: 1.5,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

// ─── Quote Card (API data display) ───────────────────────────
class _QuoteCard extends StatelessWidget {
  final QuoteModel quote;
  final int index;

  const _QuoteCard({required this.quote, required this.index});

  static const List<Color> _colors = [
    Color(0xFF1565C0),
    Color(0xFF00695C),
    Color(0xFF4527A0),
    Color(0xFFE65100),
    Color(0xFF2E7D32),
  ];

  @override
  Widget build(BuildContext context) {
    final color = _colors[index % _colors.length];
    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: color.withOpacity(0.2)),
        boxShadow: [
          BoxShadow(
            color: color.withOpacity(0.08),
            blurRadius: 8,
            offset: const Offset(0, 3),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Quote icon + content
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Icon(Icons.format_quote, color: color, size: 28),
              const SizedBox(width: 8),
              Expanded(
                child: Text(
                  quote.content,
                  style: const TextStyle(
                    fontSize: 15,
                    color: AppTheme.textDark,
                    fontStyle: FontStyle.italic,
                    height: 1.5,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          // Author
          Align(
            alignment: Alignment.bottomRight,
            child: Text(
              '— ${quote.author}',
              style: TextStyle(
                fontSize: 13,
                color: color,
                fontWeight: FontWeight.w600,
              ),
            ),
          ),
          // Tags
          if (quote.tags.isNotEmpty) ...[
            const SizedBox(height: 8),
            Wrap(
              spacing: 6,
              children: quote.tags
                  .map(
                    (tag) => Container(
                      padding: const EdgeInsets.symmetric(
                          horizontal: 8, vertical: 3),
                      decoration: BoxDecoration(
                        color: color.withOpacity(0.08),
                        borderRadius: BorderRadius.circular(12),
                      ),
                      child: Text(
                        '#$tag',
                        style: TextStyle(
                          fontSize: 11,
                          color: color,
                        ),
                      ),
                    ),
                  )
                  .toList(),
            ),
          ],
        ],
      ),
    );
  }
}

// ─── Data class (private) ────────────────────────────────────
class _HealthTip {
  final String emoji;
  final String title;
  final String description;
  final Color color;

  const _HealthTip({
    required this.emoji,
    required this.title,
    required this.description,
    required this.color,
  });
}

