import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../providers/doctor_provider.dart';
import '../theme/app_theme.dart';
import '../widgets/common_widgets.dart';

// Screen 4: Doctor Detail Screen
// Syllabus coverage:
//   • Named route with arguments (Lab 4)
//   • StatelessWidget + Consumer (Lab 5)
//   • Row, Column, Stack, Container (Lab 2)
//   • Custom widgets (Lab 6)
//   • Responsive layout (Lab 3)
class DoctorDetailScreen extends StatelessWidget {
  const DoctorDetailScreen({super.key});

  @override
  Widget build(BuildContext context) {
    final doctorId = ModalRoute.of(context)!.settings.arguments as String;
    final doctor = context.read<DoctorProvider>().getDoctorById(doctorId);

    if (doctor == null) {
      return Scaffold(
        appBar: AppBar(title: const Text('Doctor Detail')),
        body: const Center(child: Text('Doctor not found.')),
      );
    }

    return Scaffold(
      body: CustomScrollView(
        slivers: [
          // ── Hero header (Syllabus: Stack, Container, gradient)
          SliverAppBar(
            expandedHeight: 240,
            pinned: true,
            backgroundColor: AppTheme.primary,
            leading: IconButton(
              icon: const Icon(Icons.arrow_back, color: Colors.white),
              onPressed: () => Navigator.pop(context),
            ),
            flexibleSpace: FlexibleSpaceBar(
              background: Container(
                decoration: const BoxDecoration(
                  gradient: LinearGradient(
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                    colors: [AppTheme.primary, Color(0xFF006064)],
                  ),
                ),
                child: Center(
                  child: Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      const SizedBox(height: 40),
                      // Avatar
                      Container(
                        width: 100,
                        height: 100,
                        decoration: BoxDecoration(
                          color: Colors.white.withValues(alpha: 0.2),
                          shape: BoxShape.circle,
                          border: Border.all(
                            color: Colors.white.withValues(alpha: 0.5),
                            width: 2,
                          ),
                        ),
                        child: Center(
                          child: Text(
                            doctor.imageEmoji,
                            style: const TextStyle(fontSize: 48),
                          ),
                        ),
                      ),
                      const SizedBox(height: 12),
                      Text(
                        doctor.name,
                        style: const TextStyle(
                          color: Colors.white,
                          fontSize: 20,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      const SizedBox(height: 4),
                      Text(
                        doctor.specialty,
                        style: const TextStyle(
                          color: Colors.white70,
                          fontSize: 14,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),

          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  // ── Stats row (Syllabus: Row, Container)
                  Row(
                    children: [
                      _StatBadge(
                        icon: Icons.star_rounded,
                        value: doctor.rating.toString(),
                        label: 'Rating',
                        color: AppTheme.warning,
                      ),
                      const SizedBox(width: 12),
                      _StatBadge(
                        icon: Icons.reviews_outlined,
                        value: '${doctor.reviewCount}',
                        label: 'Reviews',
                        color: AppTheme.primary,
                      ),
                      const SizedBox(width: 12),
                      _StatBadge(
                        icon: Icons.work_history_outlined,
                        value: doctor.experience,
                        label: 'Experience',
                        color: AppTheme.success,
                      ),
                    ],
                  ),

                  const SizedBox(height: 20),
                  const Divider(),

                  // ── About section (Syllabus: Text, Column)
                  const Padding(
                    padding: EdgeInsets.symmetric(vertical: 12),
                    child: Text(
                      'About',
                      style: TextStyle(
                        fontSize: 17,
                        fontWeight: FontWeight.bold,
                        color: AppTheme.textDark,
                      ),
                    ),
                  ),
                  Text(
                    doctor.about,
                    style: const TextStyle(
                      fontSize: 14,
                      color: AppTheme.textMedium,
                      height: 1.6,
                    ),
                  ),

                  const SizedBox(height: 16),
                  const Divider(),

                  // ── Info tiles (Syllabus: custom widgets, Row)
                  const Padding(
                    padding: EdgeInsets.symmetric(vertical: 12),
                    child: Text(
                      'Details',
                      style: TextStyle(
                        fontSize: 17,
                        fontWeight: FontWeight.bold,
                        color: AppTheme.textDark,
                      ),
                    ),
                  ),
                  InfoTile(
                    icon: Icons.local_hospital_outlined,
                    label: 'Hospital',
                    value: doctor.hospital,
                  ),
                  InfoTile(
                    icon: Icons.schedule_outlined,
                    label: 'Available',
                    value: doctor.availableTime,
                    iconColor: AppTheme.success,
                  ),
                  InfoTile(
                    icon: Icons.medical_services_outlined,
                    label: 'Specialty',
                    value: doctor.specialty,
                    iconColor: AppTheme.accent,
                  ),

                  const SizedBox(height: 24),

                  // ── Book Appointment button (Syllabus: ElevatedButton)
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton.icon(
                      onPressed: () => Navigator.pushNamed(
                        context,
                        '/book-appointment',
                        arguments: doctor.id,
                      ),
                      icon: const Icon(Icons.calendar_month),
                      label: const Text('Book Appointment'),
                      style: ElevatedButton.styleFrom(
                        padding: const EdgeInsets.symmetric(vertical: 16),
                      ),
                    ),
                  ),
                  const SizedBox(height: 32),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

// ─── Private helper widget ────────────────────────────────────
class _StatBadge extends StatelessWidget {
  final IconData icon;
  final String value;
  final String label;
  final Color color;

  const _StatBadge({
    required this.icon,
    required this.value,
    required this.label,
