// Screen 8: Profile Screen
// Syllabus coverage:
//   • StatefulWidget + setState (Lab 5)
//   • Form validation (Lab 7b)
//   • Provider read/watch (Lab 5)
//   • Custom widgets (Lab 6)
//   • Styling with themes (Lab 6b)
//   • Responsive layout (Lab 3)
class ProfileScreen extends StatefulWidget {
  const ProfileScreen({super.key});

  @override
  State<ProfileScreen> createState() => _ProfileScreenState();
}

class _ProfileScreenState extends State<ProfileScreen> {
  bool _isEditing = false;

  final _formKey = GlobalKey<FormState>();
  late TextEditingController _nameCtrl;
  late TextEditingController _emailCtrl;
  late TextEditingController _phoneCtrl;
  late TextEditingController _bloodGroupCtrl;
  late TextEditingController _dobCtrl;
  late TextEditingController _addressCtrl;

  @override
  void initState() {
    super.initState();
    final profile = context.read<ProfileProvider>().profile;
    _nameCtrl = TextEditingController(text: profile.name);
    _emailCtrl = TextEditingController(text: profile.email);
    _phoneCtrl = TextEditingController(text: profile.phone);
    _bloodGroupCtrl = TextEditingController(text: profile.bloodGroup);
    _dobCtrl = TextEditingController(text: profile.dateOfBirth);
    _addressCtrl = TextEditingController(text: profile.address);
  }

  @override
  void dispose() {
    _nameCtrl.dispose();
    _emailCtrl.dispose();
    _phoneCtrl.dispose();
    _bloodGroupCtrl.dispose();
    _dobCtrl.dispose();
    _addressCtrl.dispose();
    super.dispose();
  }

  void _saveProfile() {
    if (!_formKey.currentState!.validate()) return;
    context.read<ProfileProvider>().updateProfile(
          UserProfile(
            name: _nameCtrl.text.trim(),
            email: _emailCtrl.text.trim(),
            phone: _phoneCtrl.text.trim(),
            bloodGroup: _bloodGroupCtrl.text.trim(),
            dateOfBirth: _dobCtrl.text.trim(),
            address: _addressCtrl.text.trim(),
          ),
        );
    setState(() => _isEditing = false);
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: const Text('Profile updated successfully!'),
        backgroundColor: AppTheme.success,
        behavior: SnackBarBehavior.floating,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(8)),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final profileProvider = context.watch<ProfileProvider>();
    final profile = profileProvider.profile;
    final apptProvider = context.watch<AppointmentProvider>();

    return Scaffold(
      appBar: AppBar(
        title: const Text('My Profile'),
        actions: [
          IconButton(
            icon: Icon(_isEditing ? Icons.close : Icons.edit),
            onPressed: () {
              if (_isEditing) {
                // Cancel – restore controllers to current profile
                _nameCtrl.text = profile.name;
                _emailCtrl.text = profile.email;
                _phoneCtrl.text = profile.phone;
                _bloodGroupCtrl.text = profile.bloodGroup;
                _dobCtrl.text = profile.dateOfBirth;
                _addressCtrl.text = profile.address;
              }
              setState(() => _isEditing = !_isEditing);
            },
          ),
          if (_isEditing)
            IconButton(
              icon: const Icon(Icons.check),
              onPressed: _saveProfile,
            ),
        ],
      ),
      body: SingleChildScrollView(
        child: Column(
          children: [
            // ── Profile header
            Container(
              width: double.infinity,
              padding: const EdgeInsets.symmetric(vertical: 32),
              decoration: const BoxDecoration(
                gradient: LinearGradient(
                  colors: [AppTheme.primary, Color(0xFF0D47A1)],
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                ),
              ),
              child: Column(
                children: [
                  // Avatar (Syllabus: Container, Stack)
                  Stack(
                    alignment: Alignment.bottomRight,
                    children: [
                      Container(
                        width: 90,
                        height: 90,
                        decoration: BoxDecoration(
                          color: Colors.white.withValues(alpha: 0.2),
                          shape: BoxShape.circle,
                          border: Border.all(
                            color: Colors.white.withValues(alpha: 0.5),
                            width: 2,
                          ),
                        ),
                        child: const Center(
                          child: Text('👤',
                              style: TextStyle(fontSize: 44)),
                        ),
                      ),
                      if (_isEditing)
                        Container(
                          padding: const EdgeInsets.all(4),
                          decoration: const BoxDecoration(
                            color: AppTheme.accent,
                            shape: BoxShape.circle,
                          ),
                          child: const Icon(
                            Icons.camera_alt,
                            color: Colors.white,
                            size: 16,
                          ),
                        ),
                    ],
                  ),
                  const SizedBox(height: 12),
                  Text(
                    profile.name,
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 20,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 4),
                  Text(
                    profile.email,
                    style: const TextStyle(
                      color: Colors.white70,
                      fontSize: 13,
                    ),
                  ),
                ],
              ),
            ),

            // ── Stats (Syllabus: Row, Consumer)
            Padding(
              padding: const EdgeInsets.all(16),
              child: Row(
                children: [
                  Expanded(
                    child: StatCard(
                      value: apptProvider.totalCount.toString(),
                      label: 'Total',
                      icon: Icons.assignment,
                      color: AppTheme.primary,
                    ),
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: StatCard(
                      value: apptProvider.upcoming.length.toString(),
                      label: 'Upcoming',
                      icon: Icons.upcoming,
                      color: AppTheme.warning,
                    ),
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: StatCard(
                      value: apptProvider.completed.length.toString(),
                      label: 'Done',
                      icon: Icons.check_circle_outline,
                      color: AppTheme.success,
                    ),
                  ),
                ],
              ),
            ),

            // ── Profile details / edit form
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: _isEditing
                  ? _EditForm(
                      formKey: _formKey,
                      nameCtrl: _nameCtrl,
                      emailCtrl: _emailCtrl,
                      phoneCtrl: _phoneCtrl,
                      bloodGroupCtrl: _bloodGroupCtrl,
                      dobCtrl: _dobCtrl,
                      addressCtrl: _addressCtrl,
                      onSave: _saveProfile,
                    )
                  : _ViewProfile(profile: profile),
            ),

            // ── Settings section (Syllabus: Switch, toggle setState)
            const SectionHeader(title: 'Settings'),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: Card(
                child: Column(
                  children: [
                    _SettingsTile(
                      icon: Icons.notifications_outlined,
                      title: 'Notifications',
                      subtitle: 'Appointment reminders',
                      trailing: Switch(
                        value: profileProvider.notificationsEnabled,
                        onChanged: (v) =>
                            context.read<ProfileProvider>().toggleNotifications(v),
                        activeThumbColor: AppTheme.primary,
                      ),
                    ),
                    const Divider(height: 1),
                    _SettingsTile(
                      icon: Icons.dark_mode_outlined,
                      title: 'Dark Mode',
                      subtitle: 'Toggle dark appearance',
                      trailing: Switch(
                        value: profileProvider.darkModeEnabled,
                        onChanged: (v) =>
                            context.read<ProfileProvider>().toggleDarkMode(v),
                        activeThumbColor: AppTheme.primary,
                      ),
                    ),
                    const Divider(height: 1),
                    _SettingsTile(
                      icon: Icons.help_outline,
                      title: 'Help & Support',
                      subtitle: 'FAQs and contact',
                      trailing: const Icon(Icons.chevron_right,
                          color: AppTheme.textLight),
                      onTap: () {},
                    ),
                    const Divider(height: 1),
                    _SettingsTile(
                      icon: Icons.info_outline,
                      title: 'About App',
                      subtitle: 'Version 1.0.0',
                      trailing: const Icon(Icons.chevron_right,
                          color: AppTheme.textLight),
                      onTap: () => _showAboutDialog(context),
                    ),
                  ],
                ),
              ),
            ),
            const SizedBox(height: 32),
          ],
        ),
      ),
    );
  }

  void _showAboutDialog(BuildContext context) {
    showAboutDialog(
      context: context,
      applicationName: 'HealthCare App',
      applicationVersion: '1.0.0',
      applicationLegalese:
          'Flutter UID Lab Project\nBVRIT HYDERABAD\nCSE – CS506PC',
    );
  }
}

